  ('dec-3', 'Shell detection — hard gate or penalty tier?', 'anvik', 'Binary hard gate.', '00000000-0000-4000-8000-000000000001', 'ruled', '2026-08-02T09:00:00+05:30', '2026-08-14T09:00:00+05:30', 'Binary hard gate. Revisit only if false positives cross 2%.'),
